import { Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const Navbar = () => {
    const { user, googleSignIn, logOut } = useAuth();

    return (
        <header className="sticky top-0 z-50 bg-[#10221c] text-white font-['Manrope']">
            <div className="max-w-[1440px] mx-auto px-6 h-16 flex items-center justify-between">
                {/* Logo */}
                <Link to="/" className="flex items-center gap-2">
                    <div className="w-8 h-5 bg-white rounded-[2px] flex items-center justify-center">
                        <span className="material-icons-outlined text-[#10221c] text-sm font-bold">architecture</span>
                    </div>
                    <span className="text-xl font-extrabold tracking-tighter uppercase">BINDASS!!</span>
                </Link>

                {/* Search (Desktop Only) */}
                <div className="flex-1 max-w-2xl mx-8 hidden lg:block">
                    <div className="relative group">
                        <span className="material-icons-outlined absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">search</span>
                        <input type="text" placeholder="Find a product" className="w-full bg-white text-slate-900 rounded-full py-2.5 pl-12 pr-4 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500 font-medium" />
                    </div>
                </div>

                {/* Icons & Auth */}
                <div className="flex items-center space-x-6">
                    <Link to="/favorites" className="hover:text-emerald-400 transition-colors hidden sm:block">
                        <span className="material-icons-outlined">favorite_border</span>
                    </Link>

                    {user ? (
                        <div className="flex items-center gap-4">
                            <Link to="/profile" className="flex items-center gap-2 group">
                                <img src={user.photoURL} alt="User" className="w-8 h-8 rounded-full border border-white/20 group-hover:border-emerald-400" />
                                <span className="text-xs uppercase font-bold hidden md:block">{user.displayName.split(' ')[0]}</span>
                            </Link>
                            <button onClick={logOut} className="text-[10px] font-bold uppercase tracking-widest border border-white/30 px-3 py-1 hover:bg-white hover:text-black transition-all">Logout</button>
                        </div>
                    ) : (
                        <button
                            onClick={async () => {
                                try {
                                    await googleSignIn();
                                } catch (error) {
                                    if (error.code !== 'auth/cancelled-popup-request') {
                                        console.error("Login failed:", error);
                                    }
                                }
                            }}
                            className="flex items-center gap-1 hover:text-emerald-400 transition-colors"
                        >
                            <span className="material-icons-outlined">person_outline</span>
                            <span className="text-xs font-bold uppercase hidden md:block">Sign In</span>
                        </button>
                    )}
                </div>
            </div>
        </header >
    );
};

export default Navbar;
